export function SlaIndicator({
  label = "{{label}}",
  percentUsed = {{percentUsed}},
  status = "{{status}}",
  dueIn = "{{dueIn}}",
}) {
  const palette = {
    "on-track": { badge: "#A8E6C1", badgeText: "#17532F", fill: "#2F8F5B" },
    "at-risk": { badge: "#E8A020", badgeText: "#4A2E00", fill: "#B4790A" },
    breached: { badge: "#B3261E", badgeText: "#FAF7F2", fill: "#B3261E" },
  }[status] ?? { badge: "#A8E6C1", badgeText: "#17532F", fill: "#2F8F5B" };
  return (
    <div style={{ width: 260, font: "12.5px/1.3 system-ui, sans-serif", color: "#241430" }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
        <span style={{ fontWeight: 700 }}>{label}</span>
        <span style={{ fontWeight: 700, textTransform: "capitalize", padding: "1px 8px", borderRadius: 999,
          fontSize: 11, background: palette.badge, color: palette.badgeText }}>{status}</span>
      </div>
      <div role="progressbar" aria-label={`${label} time used`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={percentUsed}
        style={{ height: 7, borderRadius: 999, background: "#24143018", overflow: "hidden" }}>
        <div className="sla-fill" style={{ height: "100%", borderRadius: 999, width: `${percentUsed}%`, background: palette.fill }} />
      </div>
      <p style={{ margin: "6px 0 0", color: "#241430b3" }}>Due in {dueIn}</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .sla-fill { transition: width .2s ease; }
        }
      `}</style>
    </div>
  );
}
